use rustc_hash::FxHashSet;
use swc_atoms::Atom;
use swc_common::SyntaxContext;
use swc_ecma_ast::*;
use swc_ecma_utils::find_pat_ids;
use swc_ecma_visit::{noop_visit_type, visit_obj_and_computed, Visit, VisitWith};

use crate::{option::MangleOptions, usage_analyzer::marks::Marks};

pub(crate) struct PreversedIdents {
    pub preserved: FxHashSet<Id>,
    pub idents: Option<Vec<Atom>>,
}

/// Returns `(preserved, unresolved)`
pub(crate) fn idents_to_preserve<N>(options: &MangleOptions, marks: Marks, n: &N) -> PreversedIdents
where
    N: for<'a> VisitWith<Preserver<'a>>,
{
    let mut v = Preserver {
        options,
        preserved: Default::default(),
        should_preserve: false,
        in_top_level: false,

        idents: Vec::new(),
        unresolved_ctx: SyntaxContext::empty().apply_mark(marks.unresolved_mark),
    };
    n.visit_with(&mut v);

    let top_level_mark = marks.top_level_ctxt.outer();

    // Force rename synthesized names
    // See https://github.com/swc-project/swc/issues/9468
    v.preserved.retain(|id| {
        options.reserved.contains(&id.0) || id.1.outer().is_descendant_of(top_level_mark)
    });

    let idents = v
        .idents
        .into_iter()
        .filter_map(|id| {
            if v.preserved.contains(&id) {
                None
            } else {
                Some(id.0)
            }
        })
        .collect();
    PreversedIdents {
        preserved: v.preserved,
        idents: if options.disable_char_freq {
            None
        } else {
            Some(idents)
        },
    }
}

pub(crate) struct Preserver<'a> {
    options: &'a MangleOptions,

    preserved: FxHashSet<Id>,

    should_preserve: bool,
    in_top_level: bool,

    idents: Vec<Id>,
    unresolved_ctx: SyntaxContext,
}

impl Preserver<'_> {
    fn is_reserved(&self, ident: &Ident) -> bool {
        self.options.reserved.contains(&ident.sym)
    }

    fn append_ident(&mut self, ident: &Ident) {
        if self.options.disable_char_freq
            || (ident.ctxt == self.unresolved_ctx && ident.sym != "arguments")
        {
            return;
        }

        self.idents.push(ident.to_id());
    }

    fn visit_non_top_level_stmts(&mut self, stmts: &[Stmt]) {
        let old_top_level = self.in_top_level;
        for stmt in stmts {
            self.in_top_level = false;
            stmt.visit_with(self);
        }
        self.in_top_level = old_top_level;
    }
}

impl Visit for Preserver<'_> {
    noop_visit_type!(fail);

    visit_obj_and_computed!();

    fn visit_block_stmt(&mut self, n: &BlockStmt) {
        self.visit_non_top_level_stmts(&n.stmts);
    }

    fn visit_function_body(&mut self, n: &FunctionBody) {
        self.visit_non_top_level_stmts(&n.stmts);
    }

    fn visit_catch_clause(&mut self, n: &CatchClause) {
        let old = self.should_preserve;

        if self.options.ie8 && !self.options.top_level.unwrap_or_default() {
            self.should_preserve = true;
            n.param.visit_with(self);
        }

        self.should_preserve = old;
        n.body.visit_with(self);
    }

    fn visit_class_decl(&mut self, n: &ClassDecl) {
        n.visit_children_with(self);

        // The renamer preserves the class name with a named class expression.
        // Allow its outer binding to change: compression can move same-named
        // declarations from separate scopes into the same scope.
        if (self.in_top_level && !self.options.top_level.unwrap_or_default())
            || self.is_reserved(&n.ident)
        {
            self.preserved.insert(n.ident.to_id());
        }
    }

    fn visit_class_expr(&mut self, n: &ClassExpr) {
        n.visit_children_with(self);

        if self.options.keep_class_names {
            if let Some(i) = &n.ident {
                self.preserved.insert(i.to_id());
            }
        }
    }

    fn visit_export_decl(&mut self, n: &ExportDecl) {
        n.visit_children_with(self);

        match &n.decl {
            Decl::Class(c) => {
                self.preserved.insert(c.ident.to_id());
            }
            Decl::Fn(f) => {
                self.preserved.insert(f.ident.to_id());
            }
            Decl::Var(v) => {
                let ids: Vec<Id> = find_pat_ids(&v.decls);
                self.preserved.extend(ids);
            }
            _ => {}
        }
    }

    fn visit_expr(&mut self, n: &Expr) {
        n.visit_children_with(self);

        if let Expr::Ident(i) = n {
            if self.should_preserve || self.is_reserved(i) {
                self.preserved.insert(i.to_id());
            }
        }
    }

    fn visit_fn_decl(&mut self, n: &FnDecl) {
        n.visit_children_with(self);

        if (self.in_top_level && !self.options.top_level.unwrap_or_default())
            || self.is_reserved(&n.ident)
            || self.options.keep_fn_names
        {
            self.preserved.insert(n.ident.to_id());
        }
    }

    fn visit_fn_expr(&mut self, n: &FnExpr) {
        n.visit_children_with(self);

        if self.options.keep_fn_names {
            if let Some(i) = &n.ident {
                self.preserved.insert(i.to_id());
            }
        }
    }

    fn visit_for_head(&mut self, n: &ForHead) {
        let old_top_level = self.in_top_level;
        // Lexical loop bindings are local to the loop. Preserving their names
        // can capture outer references moved into the right-hand expression by
        // compression. `var` bindings still belong to the enclosing scope.
        if let ForHead::VarDecl(decl) = n {
            if decl.kind != VarDeclKind::Var {
                self.in_top_level = false;
            }
        }

        n.visit_children_with(self);
        self.in_top_level = old_top_level;
    }

    fn visit_ident(&mut self, i: &Ident) {
        self.append_ident(i);
    }

    fn visit_module_items(&mut self, n: &[ModuleItem]) {
        for n in n {
            self.in_top_level = true;
            n.visit_with(self);
        }
    }

    fn visit_module_export_name(&mut self, _: &ModuleExportName) {}

    fn visit_pat(&mut self, n: &Pat) {
        n.visit_children_with(self);

        if let Pat::Ident(i) = n {
            if self.should_preserve || self.is_reserved(&i.id) {
                self.preserved.insert(i.to_id());
            }
        }
    }

    fn visit_script(&mut self, n: &Script) {
        for n in n.body.iter() {
            self.in_top_level = true;
            n.visit_with(self);
        }
    }

    fn visit_var_declarator(&mut self, n: &VarDeclarator) {
        n.visit_children_with(self);

        if self.in_top_level && !self.options.top_level.unwrap_or_default() {
            let old = self.should_preserve;
            self.should_preserve = true;
            n.name.visit_with(self);
            self.should_preserve = old;
            return;
        }

        if self.options.keep_fn_names {
            match n.init.as_deref() {
                Some(Expr::Fn(..)) | Some(Expr::Arrow(..)) => {
                    let old = self.should_preserve;
                    self.should_preserve = true;
                    n.name.visit_with(self);
                    self.should_preserve = old;
                }
                _ => {}
            }
        }
    }
