            let mut visitor = optimizer(
                self.marks,
                self.options,
                self.mangle_options,
                &mut data,
                self.mode,
                &mut self.static_alias_state,
            );
            n.visit_mut_with(&mut visitor);

            self.changed |= visitor.changed();

